Action: plot_chart({'query': "WITH establishment_stats AS (\n    SELECT \n        e.gmap_id,\n        e.name,\n        e.avg_rating,\n        CASE \n            WHEN e.avg_rating < 4.0 THEN '< 4.0'\n            WHEN e.avg_rating >= 4.0 AND e.avg_rating < 4.3 THEN '4.0 - 4.2'\n            WHEN e.avg_rating >= 4.3 AND e.avg_rating < 4.6 THEN '4.3 - 4.5'\n            ELSE '4.6 - 5.0'\n        END AS rating_bracket,\n        COUNT(DISTINCT i.inspection_id) AS total_inspections,\n        COUNT(v.violation_id) AS total_violations,\n        SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) AS critical_violations,\n        COUNT(v.violation_id) * 1.0 / COUNT(DISTINCT i.inspection_id) AS violations_per_inspection\n    FROM establishments e\n    JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE e.avg_rating IS NOT NULL\n    GROUP BY e.gmap_id, e.name, e.avg_rating, e.slchd_establishment_key\n)\nSELECT \n    rating_bracket,\n    ROUND(AVG(violations_per_inspection), 2) AS avg_violations_per_inspection\nFROM establishment_stats\nGROUP BY rating_bracket\nORDER BY rating_bracket ASC", 'y': 'avg_violations_per_inspection', 'title': 'Average Violations per Inspection by Google Rating Bracket', 'chart_type': 'bar', 'x': 'rating_bracket'})

